import cv2
import numpy as np

def bright_mask(image,t):
    gray = cv2.cvtColor(image,cv2.COLOR_BGR2GRAY)
    return cv2.threshold(gray,t,255,cv2.THRESH_BINARY)[1]

def count_pixels(mask):
    return int(np.count_nonzero(mask))

image = np.array([[[0,0,0],[255,255,255]]],np.uint8)
assert count_pixels(bright_mask(image,100))==1
print('组合验证通过')
